from threetears.evals import Eval

from unitprice import unit_price

def shelf_label(case):
    """The unit-price label the printer prints for the line."""
    return {"label": unit_price(case["price"], case["size"]).label}


def as_audited(case, out):
    """The label is the one the shop manager signed off."""
    return out["label"] == case["audited_label"]

audit = Eval("data/shelf_audit.jsonl", runner=shelf_label, grader=[as_audited], k=1)
